fn checkpoint_corpus() -> Value {
    serde_json::from_str(include_str!("../🛂️checkpoint/🧫️fixtures/🔣️.json")).unwrap()
}

fn run_checkpoint_case(row: &Value) -> Value {
    let depth = usize::try_from(row["depth"].as_u64().unwrap()).unwrap();
    let mut chain = vec![CancelToken::root_now()];
    for index in 1..depth {
        chain.push(chain[index - 1].child_now());
    }
    let token = chain.last().unwrap().clone();
    let other_token = CancelToken::root_now();
    let progress = Rc::new(Cell::new(0));
    let mut observer = Observer { token: token.clone(), armed: Rc::new(Cell::new("none")), progress: progress.clone(), max_attempts: 1 };
    let mut control = PublicationControl::new(PublicationLimits { max_attempts: 1, max_token_nodes: u32::try_from(row["maxTokenNodes"].as_u64().unwrap()).unwrap() }, &token, &mut observer).unwrap();
    let transaction = control.try_begin().unwrap();
    let reference = parking_lot::Mutex::new(());
    let reference_guard = reference.try_lock().unwrap();
    let mut outcomes = Vec::new();
    for action in row["actions"].as_array().unwrap() {
        match action.as_str().unwrap() {
            "checkpoint" => outcomes.push(match transaction.checkpoint() {
                Ok(()) => "live",
                Err(PublicationError::Cancelled) => "cancelled",
                Err(PublicationError::Parked) => "parked",
                Err(error) => panic!("unexpected admitted checkpoint refusal: {error}"),
            }),
            "cancel-current" => token.cancel_now(),
            "park-current" => resolve_ready(token.park()),
            "unpark-current" => resolve_ready(token.unpark()),
            "cancel-parent" => chain[0].cancel_now(),
            "park-parent" => resolve_ready(chain[0].park()),
            "unpark-parent" => resolve_ready(chain[0].unpark()),
            "cancel-other" => other_token.cancel_now(),
            action => panic!("unknown checkpoint action: {action}"),
        }
    }
    let probe_token = CancelToken::root_now();
    let mut probe_observer = Observer { token: probe_token.clone(), armed: Rc::new(Cell::new("none")), progress: Rc::new(Cell::new(0)), max_attempts: 2 };
    let mut probe = PublicationControl::new(PublicationLimits { max_attempts: 2, max_token_nodes: 1 }, &probe_token, &mut probe_observer).unwrap();
    let gate_held = matches!(probe.try_begin(), Err(PublicationError::Busy));
    assert_eq!(gate_held, reference.try_lock().is_none(), "independent held gate");
    drop(transaction);
    drop(reference_guard);
    let reacquired = probe.try_begin().is_ok();
    assert_eq!(reacquired, reference.try_lock().is_some(), "independent released gate");
    let observation = json!({ "outcomes": outcomes, "attempts": control.attempts(), "progressEvents": progress.get(), "gateHeld": gate_held, "reacquired": reacquired });
    drop(probe);
    drop(probe_observer);
    drop(probe_token);
    drop(control);
    drop(observer);
    drop(token);
    while chain.pop().is_some() {}
    observation
}

#[test]
fn transaction_checkpoint_fixture_case() {
    let corpus = checkpoint_corpus();
    let id = match std::env::var("SEMIO_PUBLICATION_CHECKPOINT_CASE_ID") {
        Ok(id) => id,
        Err(_) => {
            let (timed_out, output) = isolated_observation("transaction_checkpoint_fixture_case", "SEMIO_PUBLICATION_CHECKPOINT_CASE_ID", "live-owner");
            let stdout = String::from_utf8(output.stdout).unwrap();
            assert!(!timed_out && output.status.success(), "timedOut={timed_out}, stdout={stdout}, stderr={}", String::from_utf8_lossy(&output.stderr));
            assert!(stdout.contains("[DEBUG] Publication checkpoint case live-owner:"));
            println!("[DEBUG] Publication checkpoint default executes in an isolated process gate");
            return;
        }
    };
    let row = corpus["cases"].as_array().unwrap().iter().find(|row| row["id"] == id).unwrap();
    let actual = run_checkpoint_case(row);
    println!("[DEBUG] Publication checkpoint case {id}: {actual}");
    assert_eq!(actual, row["expected"], "{id}");
}

#[test]
fn transaction_checkpoints_execute_under_distinct_process_gates() {
    let corpus = checkpoint_corpus();
    let rows = corpus["cases"].as_array().unwrap();
    assert_eq!(rows.len(), 8);
    let mut failures = Vec::new();
    for row in rows {
        let id = row["id"].as_str().unwrap();
        let (timed_out, output) = isolated_observation("transaction_checkpoint_fixture_case", "SEMIO_PUBLICATION_CHECKPOINT_CASE_ID", id);
        let observed = String::from_utf8(output.stdout).unwrap();
        let witness = format!("[DEBUG] Publication checkpoint case {id}:");
        if timed_out || !output.status.success() || !observed.contains(&witness) {
            failures.push(format!("{id}: timedOut={timed_out}, status={}, stdout={observed}, stderr={}", output.status, String::from_utf8_lossy(&output.stderr)));
        }
        println!("[DEBUG] Publication checkpoint subprocess {id}: status={}, timedOut={timed_out}", output.status);
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
